(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.017-t*0.27)*18 + Math.sin(x*0.015+t*0.33)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.011+t*0.17)*8 + Math.sin((x+y)*0.009-t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 70+Math.cos(t*0.4)*55, 0.075, 2.1, 0.9],
    [320+Math.cos(t*0.5)*110, 170+Math.sin(t*0.7)*55, 0.095, 1.8, 1.1],
    [240+Math.sin(t*0.3+2)*150, 110+Math.cos(t*0.5+1)*95, 0.055, 2.4, 0.8],
    [100+Math.cos(t*0.8+1)*90, 190+Math.sin(t*0.6+3)*65, 0.11, 1.6, 1.2],
    [380+Math.sin(t*0.4+4)*100, 50+Math.cos(t*0.9+2)*75, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.35+5)*130, 210+Math.sin(t*0.55)*85, 0.085, 2.0, 1.0],
    [60+Math.sin(t*0.65+3)*70, 120+Math.cos(t*0.45+2)*80, 0.1, 1.4, 1.3],
    [420+Math.cos(t*0.55+1)*60, 140+Math.sin(t*0.75+4)*50, 0.08, 2.2, 0.85]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const tw = 8;
  const act=aS/tw, inh=iS/tw, harm=hS/tw;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.3)*0.2+Math.sin((sx-sy)*0.09-t*1.8)*0.2;
  const bg3 = Math.sin(sx*0.07+t*0.5)*Math.sin(sy*0.065-t*0.4)*0.25;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = (Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const sp2 = Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const spiral = sp1+sp2;
  const fbm = Math.sin(sx*0.06+t*0.3)*Math.sin(sy*0.055-t*0.25)*0.3
    + Math.sin(sx*0.12-sy*0.1+t*0.6)*0.15
    + Math.sin((sx*0.5|0)*0.15+(sy*0.5|0)*0.15+t*0.4)*0.1;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral+harm*0.2+fbm*0.15)*2.4);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin(sx*0.22-t*0.8)*Math.sin(sy*0.2+t*0.6)*0.3)*1.6)*0.25;
  const contour = (1-Math.pow(Math.abs(Math.sin(reaction*6)),8))*0.12;
  const pulse = 0.92+Math.sin(t*0.8)*0.08;
  const blend = (reaction*0.65+cell*0.2+contour)*pulse;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[15,95,115],[18,145,130],
    [45,175,140],[120,195,110],[190,200,75],
    [220,175,55],[230,130,60],[215,85,65],
    [185,50,70],[120,28,60],[60,15,50],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm = f*f*(3-2*f);
  const lum=0.78+Math.sin(reaction*Math.PI)*0.22;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.05:0.95;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*120)|0)
  ];
}
